@php
$localHistory=[];
if(isset($village['census'])){$c=$village['census'];$localHistory[]=['year'=>2011,'population'=>$c['population']??null,'households'=>$c['households']??null,'literates'=>$c['literate']??null];}
elseif(isset($village['population'])){$localHistory[]=['year'=>(int)($year??2011),'population'=>$village['population'],'households'=>$village['households']??null,'literates'=>$village['literate']??null];}
foreach($village['census_history']??[] as $history){if(isset($history['pca']['values'])){$v=$history['pca']['values'];$localHistory[]=['year'=>2001,'population'=>$v['TOT_P']??null,'households'=>$v['No_HH']??null,'literates'=>$v['P_LIT']??null];}}
usort($localHistory,fn($a,$b)=>$a['year']<=>$b['year']);
@endphp
<section id="local-history" class="panel census-history"><h2>Population, households &amp; education graphs</h2><p class="small" data-methodology-note>Dated source records retain their original geography. A code correspondence does not establish unchanged boundaries or a comparable growth series.</p>@foreach(['population'=>'Population','households'=>'Households','literates'=>'Literate people'] as $field=>$label)@if(collect($localHistory)->contains(fn($row)=>($row[$field]??null)!==null))<section class="history-line" data-history-chart><h3>{{ $label }}</h3><script type="application/json" class="history-chart-data">{!! json_encode(['rows'=>$localHistory,'series'=>[['key'=>$field,'label'=>$label]],'unit'=>$field==='households'?'households':'people','singleValueBar'=>true],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) !!}</script><div class="history-controls"><label>From<select data-chart-from>@foreach($localHistory as $point)<option>{{ $point['year'] }}</option>@endforeach</select></label><label>To<select data-chart-to>@foreach($localHistory as $point)<option @selected($loop->last)>{{ $point['year'] }}</option>@endforeach</select></label></div><div class="history-legend"></div><div class="history-plot"></div><p class="history-readout" role="status"></p></section>@endif @endforeach</section>
